def solve():
    for m in range(1, 10):
        # Base-7 representation of m
        digits_m = []
        temp_m = m
        while temp_m > 0:
            digits_m.append(temp_m % 7)
            temp_m //= 7
        rep_m = digits_m[::-1]

        # n = (b_m b_{m-1} ... b_0)_7
        # b_m in {1...6}, b_i in {0...6}
        # n = sum_{i=0}^{m-1} a_i

        # We can iterate over all possible digits b_0, ..., b_m
        # Since m is small, we can use itertools.product
        import itertools
        for b in itertools.product(range(7), repeat=m+1):
            # b is (b_0, b_1, ..., b_m)
            # Leading digit b_m must be non-zero
            if b[m] == 0:
                continue

            # n = sum(b_i * 7^i for i in range(m+1))
            n = sum(b[i] * (7**i) for i in range(m+1))

            total_sum = 0
            possible = True
            for i in range(m):
                bi = b[i]
                possible_ai = []
                for j in range(len(rep_m)):
                    if rep_m[j] == bi:
                        new_rep = rep_m[:j] + rep_m[j+1:]
                        ai = 0
                        if new_rep:
                            for digit in new_rep:
                                ai = ai * 7 + digit
                        possible_ai.append(ai)

                if not possible_ai:
                    possible = False
                    break
                else:
                    # Let's assume if there are multiple, we pick one that works?
                    # Or perhaps the problem implies they all work.
                    # Let's just pick the first one for now.
                    total_sum += possible_ai[0]

            if possible and total_sum == n:
                print(f"n={n}, m={m}, digits_n={b[::-1]}, digits_m={rep_m}, sum={total_sum}")

