def solve():
    solutions = []
    for m in range(1, 11):
        c = [0] * (m + 1)
        for j in range(m + 1):
            term1 = 7**j
            term2 = 0
            if 1 <= j <= m:
                term2 += j * (7**(j-1))
            term3 = 0
            if 0 <= j <= m-2:
                term3 += (m-1-j) * (7**j)
            c[j] = term1 - term2 - term3

        # Solving \sum c_j b_j = 0
        # We can use recursion with a bit of pruning.
        def find_all(j, current_sum):
            if j == m + 1:
                if current_sum == 0:
                    return [[]]
                return []

            # Pruning:
            # The maximum possible sum from j to m:
            # \sum_{k=j}^m c_k b_k
            # Max/min values of c_k for k >= j.
            max_val = 0
            min_val = 0
            for k in range(j, m + 1):
                if c[k] > 0:
                    max_val += c[k] * 6
                else:
                    min_val += c[k] * 6 # c[k] is negative, so c[k]*6 is the minimum

            if current_sum + min_val > 0 or current_sum + max_val < 0:
                return []

            res = []
            start = 1 if j == m else 0
            for bj in range(start, 7):
                sub_solutions = find_all(j + 1, current_sum + c[j] * bj)
                for sol in sub_solutions:
                    res.append([bj] + sol)
            return res

        sols = find_all(0, 0)
        for sol in sols:
            # sol is [b_0, b_1, ..., b_m]
            n = 0
            for i in range(m + 1):
                n += sol[i] * 7**i
            solutions.append(n)

    return sorted(list(set(solutions)))

