def solve_final():
    # The problem is n = \sum_{i=0}^{m-1} a_i
    # a_i is obtained by removing the i-th digit b_i from n.
    # We found that solutions only exist for m=7.
    # For m=7, n = b_7 7^7 + b_6 7^6 + b_5 7^5 + b_4 7^4 + b_3 7^3 + b_2 7^2 + b_1 7^1 + b_0 7^0.
    # The equation is -6b_0 - 29b_1 - 161b_2 - 833b_3 - 3773b_4 - 12005b_5 + 16807b_6 = 0.
    # Here b_7 \in {1..6} and b_0..b_6 \in {0..6}.
    # So for each b_7 \in {1..6}, we want to count the number of (b_0..b_6) that satisfy this.

    count = 0
    for b_7 in range(1, 7):
        for b_6 in range(7):
            for b_5 in range(7):
                for b_4 in range(7):
                    for b_3 in range(7):
                        for b_2 in range(7):
                            for b_1 in range(7):
                                for b_0 in range(7):
                                    if -6*b_0 - 29*b_1 - 161*b_2 - 833*b_3 - 3773*b_4 - 12005*b_5 + 16807*b_6 == 0:
                                        count += 1
    return count

