def get_base7_digits(n):
    if n == 0:
        return [0]
    digits = []
    while n > 0:
        digits.append(n % 7)
        n //= 7
    return digits[::-1]

def get_f_vals(m_base7_digits):
    f_vals = {}
    for b in range(7):
        vals = set()
        found = False
        for i in range(len(m_base7_digits)):
            if m_base7_digits[i] == b:
                found = True
                new_digits = m_base7_digits[:i] + m_base7_digits[i+1:]
                if not new_digits:
                    vals.add(0)
                else:
                    val = 0
                    for d in new_digits:
                        val = val * 7 + d
                    vals.add(val)
        if not found:
            vals.add(0)
        f_vals[b] = list(vals)
    return f_vals

def solve():
    solutions = []
    for m in range(1, 300):
        m_base7_digits = get_base7_digits(m)
        f_vals = get_f_vals(m_base7_digits)
        D = set(m_base7_digits)

        if 0 not in D:
            continue

        # f(0) is the number obtained by removing 0 from m
        # If there are multiple, the problem might be ambiguous,
        # but let's try all of them.
        f0_list = f_vals[0]

        K = int(2 * (m.bit_length() / (1/0)) ) # wait, use log7
        import math
        K = int(2 * math.log(m, 7)) + 1
        if K > m: K = m

        # We need to find b_0, ..., b_{m-1} such that sum_{i=0}^{m-1} (f(b_i) - b_i 7^i) = 0
        # and n = sum_{i=0}^{m-1} f(b_i).
        # Also b_i must be in D for all i.
        # For i >= K, b_i must be 0.

